    int P(int n)const{return MulDiv(n,static_cast<int>(dpi_),96);}
    HWND Add(const wchar_t* type,const wchar_t* label,DWORD style,int id=0){const auto w=CreateWindowExW(type==std::wstring(L"EDIT")?WS_EX_CLIENTEDGE:0,type,label,WS_CHILD|WS_VISIBLE|style,0,0,0,0,window_,reinterpret_cast<HMENU>(static_cast<INT_PTR>(id)),GetModuleHandleW(nullptr),nullptr);if(!w)throw std::runtime_error("Windows control creation failed.");SendMessageW(w,WM_SETFONT,reinterpret_cast<WPARAM>(font_),TRUE);controls_.push_back({w,id});if(std::wstring(type)==L"BUTTON")SetClassLongPtrW(w,GCLP_HCURSOR,reinterpret_cast<LONG_PTR>(LoadCursorW(nullptr,IDC_HAND)));return w;}
