    void Label(const wchar_t* text,int x,int y,int width){const auto w=Add(L"STATIC",text,SS_LEFT);labels_.push_back({w,x,y,width});MoveWindow(w,P(x),P(y),P(width),P(23),TRUE);}
    void ScaleFonts(UINT next){const auto scaled=[&](HFONT old){LOGFONTW f{};GetObjectW(old,sizeof(f),&f);f.lfHeight=MulDiv(f.lfHeight,static_cast<int>(next),static_cast<int>(dpi_));return CreateFontIndirectW(&f);};const auto normal=scaled(font_),mono=scaled(mono_),title=scaled(title_);if(!normal||!mono||!title){DeleteObject(normal);DeleteObject(mono);DeleteObject(title);return;}const auto old=font_,oldMono=mono_,oldTitle=title_;font_=normal;mono_=mono;title_=title;dpi_=next;for(const auto& c:controls_)SendMessageW(c.first,WM_SETFONT,reinterpret_cast<WPARAM>(font_),TRUE);SendMessageW(descriptor_,WM_SETFONT,reinterpret_cast<WPARAM>(mono_),TRUE);SendMessageW(report_,WM_SETFONT,reinterpret_cast<WPARAM>(mono_),TRUE);DeleteObject(old);DeleteObject(oldMono);DeleteObject(oldTitle);}
    void Position(HWND w,int x,int y,int width,int height){MoveWindow(w,P(x),P(y),P(width),P(height),TRUE);}
    HWND Find(int id){for(const auto& c:controls_)if(c.second==id)return c.first;return nullptr;}
    void Status(const std::wstring& message){notice_=message;SetWindowTextW(status_,message.c_str());}
    Fixture::Scenario Form(){auto s=scenario_;const auto number=[&](HWND w,int base,unsigned maximum){const auto text=Text(w);wchar_t* end=nullptr;const auto n=wcstoul(text.c_str(),&end,base);if(text.empty()||end!=text.c_str()+text.size()||n>maximum)throw std::invalid_argument("VID/PID must be hexadecimal; report length must be decimal 1..64.");return n;};s.vid=static_cast<std::uint16_t>(number(vid_,16,65535));s.pid=static_cast<std::uint16_t>(number(pid_,16,65535));s.input_bytes=static_cast<std::uint32_t>(number(bytes_,10,64));s.report_descriptor=Fixture::ParseHex(Narrow(Text(descriptor_)));s.reports={{0,Fixture::ParseHex(Narrow(Text(report_)),64)}};Fixture::Validate(s);return s;}
    void Populate(const Fixture::Scenario& s){scenario_=s;SetWindowTextW(descriptor_,Wide(Fixture::Hex(s.report_descriptor)).c_str());const auto r=s.reports.empty()?Fixture::Bytes(s.input_bytes):s.reports.front().data;SetWindowTextW(report_,Wide(Fixture::Hex(r)).c_str());std::wostringstream v,p;v<<std::hex<<std::uppercase<<s.vid;p<<std::hex<<std::uppercase<<s.pid;SetWindowTextW(vid_,v.str().c_str());SetWindowTextW(pid_,p.str().c_str());SetWindowTextW(bytes_,std::to_wstring(s.input_bytes).c_str());}
    void Execute(int id){try{
        if(id==Mouse||id==Keyboard){Populate(id==Mouse?Fixture::Mouse():Fixture::Keyboard());Status(L"Example loaded. Validate, create, then send deliberately. Editing does not change an already connected device.");}
        else if(id==Validate){const auto result=Vdevice::Validate_Device(Fixture::Configuration(Form()));if(!result)throw std::runtime_error(result.message);Status(L"Valid USB structure and fixed-size HID input layout. Offline validation does not prove Windows/application compatibility.");}
        else if(id==Load){const auto path=Choose(window_,false);if(!path.empty()){Populate(Fixture::Parse(Read(path)));Status(L"Fixture loaded. Nothing was connected or sent.");}}
        else if(id==Save){const auto s=Form();const auto path=Choose(window_,true);if(!path.empty()){Write(path,Fixture::Serialize(s));Status(L"Fixture exported for HID Fixture Studio / Input CI Runner. Current report is scheduled at 0 microseconds.");}}
        else if(id==Contact)ShellExecuteW(window_,L"open",L"https://discord.com/channels/@me",nullptr,nullptr,SW_SHOWNORMAL);
        else if(id==Setup){const auto path=Directory()/L"Dependencies"/L"VdeviceSetup.exe";if(!std::filesystem::exists(path))throw std::runtime_error("Dependencies/VdeviceSetup.exe is missing. Download the complete release ZIP.");ShellExecuteW(window_,L"open",path.c_str(),nullptr,path.parent_path().c_str(),SW_SHOWNORMAL);}
        else if(preview_)Status(L"Preview mode: live device creation and input sending are disabled.");
        else if(id==Create){if(!Admin()){Status(L"Live access requires administrator rights. An elevation prompt will open; no device has been created here.");Elevate(window_);return;}session_.Create(Form());}
        else if(id==Delete)session_.Delete();
        else if(id==Send){const auto s=Form();session_.Send(s.reports.front().data);}
    }catch(const std::exception& error){Status(L"Error: "+Wide(error.what()));}}
    void Build(){
        dpi_=GetDpiForWindow(window_);font_=CreateFontW(-P(15),0,0,0,FW_NORMAL,FALSE,FALSE,FALSE,DEFAULT_CHARSET,OUT_DEFAULT_PRECIS,CLIP_DEFAULT_PRECIS,CLEARTYPE_QUALITY,DEFAULT_PITCH,L"Segoe UI");mono_=CreateFontW(-P(14),0,0,0,FW_NORMAL,FALSE,FALSE,FALSE,DEFAULT_CHARSET,OUT_DEFAULT_PRECIS,CLIP_DEFAULT_PRECIS,CLEARTYPE_QUALITY,FIXED_PITCH,L"Consolas");title_=CreateFontW(-P(29),0,0,0,FW_SEMIBOLD,FALSE,FALSE,FALSE,DEFAULT_CHARSET,OUT_DEFAULT_PRECIS,CLIP_DEFAULT_PRECIS,CLEARTYPE_QUALITY,DEFAULT_PITCH,L"Segoe UI");
        Button(L"Mouse fixture",Mouse);Button(L"Keyboard fixture",Keyboard);Button(L"Load JSON",Load);Button(L"Export JSON",Save);Button(L"Driver setup",Setup);Button(L"Validate offline",Validate);Button(L"Create device",Create);Button(L"Disconnect",Delete);Button(L"Send raw report",Send);Button(L"Add titancsa on Discord",Contact);
        Label(L"Vendor ID (hex)",28,178,160);Label(L"Product ID (hex)",228,178,160);Label(L"Input report length (bytes)",428,178,240);
        vid_=Add(L"EDIT",L"",ES_AUTOHSCROLL|WS_TABSTOP);pid_=Add(L"EDIT",L"",ES_AUTOHSCROLL|WS_TABSTOP);bytes_=Add(L"EDIT",L"",ES_AUTOHSCROLL|WS_TABSTOP);
        SendMessageW(vid_,EM_SETLIMITTEXT,4,0);SendMessageW(pid_,EM_SETLIMITTEXT,4,0);SendMessageW(bytes_,EM_SETLIMITTEXT,2,0);
        Label(L"Raw HID report descriptor",28,254,500);descriptor_=Add(L"EDIT",L"",ES_MULTILINE|ES_AUTOVSCROLL|ES_WANTRETURN|WS_VSCROLL|WS_TABSTOP);SendMessageW(descriptor_,WM_SETFONT,reinterpret_cast<WPARAM>(mono_),TRUE);SendMessageW(descriptor_,EM_SETLIMITTEXT,16512,0);
        Label(L"Raw input report (hex bytes, including report ID when present)",28,485,900);report_=Add(L"EDIT",L"",ES_MULTILINE|ES_AUTOVSCROLL|WS_VSCROLL|WS_TABSTOP);SendMessageW(report_,WM_SETFONT,reinterpret_cast<WPARAM>(mono_),TRUE);SendMessageW(report_,EM_SETLIMITTEXT,384,0);
        status_=Add(L"EDIT",L"",ES_MULTILINE|ES_READONLY|ES_AUTOVSCROLL|WS_VSCROLL);Populate(scenario_);Layout();
        Status(preview_?L"Offline preview. No driver opened; no device created; no input sent.":L"Disconnected. Start with a fixture, validate offline, then explicitly create the virtual device. Raw reports affect Windows.");
        if(!preview_)session_.Start(window_);
    }
